self.KB_CONTENT["card:783378"]={"id":"card:783378","ty":"card","sourceId":"783378","title":"『抵押借款查詢作業』中的『還息方式 (TJ011)』為何？","ver":"GP4以上","topic":"固定","keywords":["固定","每月"],"y":"other","answer":"* 分別為1.每月固定日計息、2.到期計息、3.每月相對日計息及9.其他。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
