self.KB_CONTENT["card:779627"]={"id":"card:779627","ty":"card","sourceId":"779627","title":"『委外工單開立』中的『幣別 (TH040)』為何？","ver":"GP4以上","topic":"銀行","keywords":["銀行","幣別","工單","匯率"],"y":"other","answer":"* 不可空白。* 預設匯率：幣別+開單日期+'O'(銀行賣出匯率)。* [F2]幣別資料查詢(CMSMF-01)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
